#include <bits/stdc++.h>
using namespace std;
class Solution {public:int latestTimeCatchTheBus(vector<int>& buses,vector<int>& passengers,int capacity){sort(buses.begin(),buses.end());sort(passengers.begin(),passengers.end());int j=0,ans=0;for(int bus:buses){int seats=capacity;while(j<(int)passengers.size()&&passengers[j]<=bus&&seats){++j;--seats;}ans=seats?bus:passengers[j-1]-1;}unordered_set<int> taken(passengers.begin(),passengers.end());while(taken.count(ans))--ans;return ans;}};
